const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfoAsync(obj) {
  return await new Promise((resolve, reject) => obj.getInfo(resolve, reject));
}

function buildRegion() {
  // Try GAUL Level1 for Chongqing; fallback to buffered point.
  const gaul1 = ee.FeatureCollection('FAO/GAUL/2015/level1');
  const filt1 = gaul1.filter(ee.Filter.and(
    ee.Filter.or(ee.Filter.eq('ADM0_NAME', 'China'), ee.Filter.eq('ADM0_NAME', 'CHINA')),
    ee.Filter.eq('ADM1_NAME', 'Chongqing')
  ));
  const filt2 = gaul1.filter(ee.Filter.and(
    ee.Filter.or(ee.Filter.eq('ADM0_NAME', 'China'), ee.Filter.eq('ADM0_NAME', 'CHINA')),
    ee.Filter.stringContains('ADM1_NAME', 'Chongqing')
  ));
  const region = ee.Algorithms.If(
    filt1.size().gt(0),
    ee.FeatureCollection(filt1).geometry(),
    ee.Algorithms.If(
      filt2.size().gt(0),
      ee.FeatureCollection(filt2).geometry(),
      ee.Geometry.Point([106.55, 29.56]).buffer(100000).bounds()
    )
  );
  return ee.Geometry(region);
}

function makeCollection(dataset, start, end, region) {
  return ee.ImageCollection(dataset)
    .filterDate(start, end)
    .filterBounds(region)
    .select(['tropospheric_NO2_column_number_density', 'qa_value']);
}

function maskNO2(img) {
  const qa = img.select('qa_value');
  const good = qa.gte(0.75);
  return img.select('tropospheric_NO2_column_number_density').updateMask(good);
}

async function computeStats(col, region, scaleMeters) {
  const nImages = await getInfoAsync(col.size());
  const maskedCol = col.map(maskNO2);
  const band = 'tropospheric_NO2_column_number_density';

  // Per-pixel sums and valid counts across time
  const sumImg = maskedCol.sum().rename(band);
  const cntImg = maskedCol.count().rename(band);
  const anyValid = cntImg.gt(0);

  // Spatial valid pixel count (any day valid)
  const validPx = await getInfoAsync(anyValid.selfMask()
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scaleMeters,
      maxPixels: 1e9,
      bestEffort: true
    }).get(band));

  // Total pixels at this scale
  const totalPx = await getInfoAsync(ee.Image.constant(1).rename('one')
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scaleMeters,
      maxPixels: 1e9,
      bestEffort: true
    }).get('one'));

  // Region-summed numerator and denominator for grand mean across all pixel-days
  const sumVals = await getInfoAsync(sumImg.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: scaleMeters,
    maxPixels: 1e9,
    bestEffort: true
  }).get(band));

  const sumCnts = await getInfoAsync(cntImg.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: scaleMeters,
    maxPixels: 1e9,
    bestEffort: true
  }).get(band));

  return {
    images: nImages || 0,
    validPixels: validPx || 0,
    totalPixels: totalPx || 0,
    coveragePct: (validPx && totalPx && totalPx > 0) ? (100.0 * validPx / totalPx) : 0,
    sumVals: sumVals,
    sumCnts: sumCnts,
    mean: (sumVals && sumCnts && sumCnts > 0) ? (sumVals / sumCnts) : null
  };
}

async function runAnalysis() {
  try {
    const region = buildRegion();
    const scale = 7000; // meters

    const p1 = { start: '2020-02-10', end: '2020-02-26', label: 'Feb10-25' };
    const p2 = { start: '2020-04-20', end: '2020-05-13', label: 'Apr20-May12' };

    // Choose dataset with fallback
    const ds1 = 'COPERNICUS/S5P/OFFL/L3_NO2';
    const ds2 = 'COPERNICUS/S5P/NRTI/L3_NO2';

    let dataset = ds1;
    let col1 = makeCollection(dataset, p1.start, p1.end, region);
    let col2 = makeCollection(dataset, p2.start, p2.end, region);
    const n1 = await getInfoAsync(col1.size());
    const n2 = await getInfoAsync(col2.size());

    if ((n1 || 0) === 0 || (n2 || 0) === 0) {
      dataset = ds2;
      col1 = makeCollection(dataset, p1.start, p1.end, region);
      col2 = makeCollection(dataset, p2.start, p2.end, region);
    }

    const nn1 = await getInfoAsync(col1.size());
    const nn2 = await getInfoAsync(col2.size());

    console.log(`Dataset: ${dataset.split('/').slice(-1)[0]}`);
    if ((nn1 || 0) === 0 || (nn2 || 0) === 0) {
      console.log(`${p1.label} Images: ${nn1 || 0}`);
      console.log(`${p2.label} Images: ${nn2 || 0}`);
      console.log('C1');
      return;
    }

    const stats1 = await computeStats(col1, region, scale);
    const stats2 = await computeStats(col2, region, scale);

    console.log(`Region: Chongqing (scale=${scale} m) total pixels: ${stats1.totalPixels}`);
    console.log(`${p1.label} Images: ${stats1.images}, ValidPx: ${stats1.validPixels} (${stats1.coveragePct.toFixed(1)}%), Mean NO2: ${stats1.mean !== null ? stats1.mean.toExponential(3) : 'null'}`);
    console.log(`${p2.label} Images: ${stats2.images}, ValidPx: ${stats2.validPixels} (${stats2.coveragePct.toFixed(1)}%), Mean NO2: ${stats2.mean !== null ? stats2.mean.toExponential(3) : 'null'}`);

    if ((stats1.validPixels || 0) === 0 || (stats2.validPixels || 0) === 0) {
      console.log('C2');
      return;
    }
    if (stats1.mean === null || stats2.mean === null || !isFinite(stats1.mean) || !isFinite(stats2.mean)) {
      console.log('C3');
      return;
    }

    const change = ((stats2.mean - stats1.mean) / stats1.mean) * 100.0;
    console.log(`Change: ${change.toFixed(1)}% (ratio ${(stats2.mean / stats1.mean).toFixed(3)})`);

    // Final answer: A if increase, else B
    const answer = stats2.mean > stats1.mean ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
